import sys, json

for line in sys.stdin:
    request = json.loads(line)
    if request["method"] == "tools/call" and request["params"]["name"] == "add":
        a, b = request["params"]["arguments"]["a"], request["params"]["arguments"]["b"]
        response = {"jsonrpc": "2.0", "id": request["id"], "result": {"sum": a + b}}
    else:
        response = {"jsonrpc": "2.0", "id": request["id"], "error": {"code": -32601, "message": "unknown method"}}
    sys.stdout.write(json.dumps(response) + "\n")
    sys.stdout.flush()
